INSERT INTO math_spiral_items (competency_id, prompt, answer_key, first_unit_id, difficulty, is_spaced, needs_graph, needs_equation_builder, translations, template, created_by) VALUES
((select id from math_competencies where code='NS1'), 'Which is larger: 0.5 or 0.45?', '0.5 (5 tenths beats 4 tenths — compare place by place, not by length)', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS1'), 'In the number 47,062 what is the 7 worth?', '7,000 (it sits in the thousands place)', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS1'), 'Which is larger: {a},{b}18 or {a},{b}81?', 'The second — the digits match until the tens place, where 8 beats 1.', NULL, 'easy', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 2, "max": 9}, "b": {"min": 1, "max": 9}}, "answer": "a*1000+b*100+81", "sigFigs": 6}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS1'), 'Write a number between 3.6 and 3.7.', 'Any of 3.61–3.69, e.g. 3.65', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS1'), 'Which is colder: −8° or −3°?', '−8° (further left on the number line, even though 8 > 3)', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS1'), 'Round {a}.{b}6 to the nearest tenth.', 'The 6 hundredths rounds the tenths digit up.', NULL, 'easy', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 1, "max": 9}, "b": {"min": 1, "max": 8}}, "answer": "a + (b+1)/10"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS1'), 'Order from least to greatest: 0.09, 0.1, 0.089.', '0.089, 0.09, 0.1 (line up the decimal places before comparing)', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS1'), 'A debit card balance goes from −$12 to −$5. Did it go up or down, and by how much?', 'Up by $7 (−5 is greater than −12)', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS1'), 'Which is larger: {a}.0{b} or {a}.{b}?', '{a}.{b} — 0{b} hundredths is smaller than {b} tenths.', NULL, 'medium', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 1, "max": 9}, "b": {"min": 1, "max": 9}}, "answer": "a + b/10"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS1'), 'On a number line, what number is exactly halfway between {a} and {b}?', 'Add them and divide by 2.', NULL, 'medium', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 2, "max": 20}, "b": {"min": 30, "max": 80, "step": 2}}, "answer": "(a+b)/2"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS1'), 'A stock price of $0.30 ''fell to a third''. What is it now?', '$0.10 — a third OF the value, not minus 3.', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS1'), 'How many hundredths are in {a}.{b}?', 'Multiply by 100.', NULL, 'medium', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 1, "max": 9}, "b": {"min": 1, "max": 9}}, "answer": "a*100 + b*10"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS1'), 'Which is larger: 0.3̄ (0.333…) or 1/3? Explain.', 'They are equal — 0.333… repeating IS 1/3.', NULL, 'hard', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS1'), 'Two decimals both start 0.4. One has 3 digits, one has 5. Which is bigger?', 'Can''t tell — length says nothing; compare place by place (0.400 vs 0.39999 vs 0.41234).', NULL, 'hard', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS1'), 'A number rounds to 6.3. What is the smallest it could be?', '6.25 (anything from 6.25 up to but not including 6.35 rounds to 6.3)', NULL, 'hard', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS2'), 'Write {a}% as a decimal.', 'Divide by 100.', NULL, 'easy', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 5, "max": 95, "step": 5}}, "answer": "a/100"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS2'), 'Write 0.6 as a fraction in lowest terms.', '3/5 (6/10 reduced)', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS2'), 'What is {a}% of {b}?', 'Turn the percent into a decimal and multiply.', NULL, 'easy', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 10, "max": 90, "step": 10}, "b": {"min": 20, "max": 400, "step": 20}}, "answer": "a*b/100"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS2'), 'You made {a} of {b} free throws. What fraction is that, and about what percent?', '{a}/{b} — divide top by bottom for the percent.', NULL, 'easy', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 3, "max": 9}, "b": {"min": 10, "max": 20, "step": 10}}, "answer": "100*a/b"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS2'), 'Which is bigger: 3/4 or 70%?', '3/4 (= 75%)', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS2'), 'A pizza is cut into 8 slices and you eat 3. What fraction is left?', '5/8', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS2'), 'A ${b} hoodie is {a}% off. What do you pay?', 'Take {a}% of the price off.', NULL, 'medium', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 10, "max": 50, "step": 10}, "b": {"min": 20, "max": 80, "step": 4}}, "answer": "b - a*b/100", "answerUnit": "$"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS2'), 'Write 7/20 as a percent.', '35% (multiply top and bottom by 5 → 35/100)', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS2'), 'A tank is 5/8 full. What percent is empty?', '37.5% (3/8 empty; 1/8 = 12.5%)', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS2'), 'Your quiz score went from {a} points to {b} points. What is the percent increase?', 'Change over ORIGINAL, times 100.', NULL, 'medium', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 20, "max": 40, "step": 5}, "b": {"min": 45, "max": 80, "step": 5}}, "answer": "100*(b-a)/a", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS2'), 'Which tip is more: 15% of $40 or 20% of $32?', '15% of $40 = $6.00; 20% of $32 = $6.40 — the second.', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS2'), '0.125 equals what fraction?', '1/8', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS2'), 'A price rises 50%, then falls 50%. Is it back where it started?', 'No — it ends at 75% of the original (the 50% down is taken off a bigger number).', NULL, 'hard', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS2'), '{a}% of a number is {b}. What is the number?', 'Divide {b} by the decimal form of {a}%.', NULL, 'hard', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 20, "max": 80, "step": 10}, "b": {"min": 12, "max": 96, "step": 12}}, "answer": "100*b/a", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='NS2'), 'Which is the best deal: 1/3 off, 30% off, or ''pay 2/3 of the price''?', '1/3 off and pay-2/3 are the same (≈33.3% off); both beat 30% off.', NULL, 'hard', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE1'), 'Write 4,500,000 in scientific notation.', '4.5 × 10^6', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE1'), 'Write 3.2 × 10^4 as an ordinary number.', '32,000', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE1'), 'Which is larger: 9 × 10^7 or 2 × 10^8?', '2 × 10^8 — compare the exponent first.', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE1'), 'Write 0.00081 in scientific notation.', '8.1 × 10^−4', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE1'), 'A phone photo is about 3 × 10^6 bytes. Say that in millions.', '3 million bytes (3 MB)', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE1'), 'Multiply: (2 × 10^{a}) × (3 × 10^{b}).', 'Multiply the fronts, add the exponents: 6 × 10^({a}+{b}).', NULL, 'easy', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 2, "max": 5}, "b": {"min": 2, "max": 5}}, "answer": "6*10^(a+b)", "sigFigs": 1}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE1'), 'Divide: (8 × 10^{a}) ÷ (4 × 10^{b}).', 'Divide the fronts, subtract the exponents: 2 × 10^({a}−{b}).', NULL, 'medium', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 6, "max": 9}, "b": {"min": 2, "max": 5}}, "answer": "2*10^(a-b)", "sigFigs": 1}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE1'), 'Put in proper scientific notation: 72 × 10^5.', '7.2 × 10^6 (the front must be between 1 and 10)', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE1'), 'A song stream moves about {a} × 10^6 bytes and your plan has {b} × 10^9 bytes. How many streams is that?', 'Divide; the powers of ten subtract.', NULL, 'medium', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 3, "max": 8}, "b": {"min": 2, "max": 10}}, "answer": "b*10^9/(a*10^6)", "sigFigs": 2}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE1'), 'How many times larger is 6 × 10^8 than 3 × 10^5?', '2,000 times (2 × 10^3)', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE1'), 'Add: 3 × 10^4 + 5 × 10^3. Why can''t you just add the fronts?', '3.5 × 10^4 — the exponents differ, so rewrite one first (30,000 + 5,000).', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE1'), 'Estimate {a},000 × {b},000 using powers of ten.', '({a}×10^3)({b}×10^3) = {a}·{b} × 10^6.', NULL, 'medium', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 2, "max": 9}, "b": {"min": 2, "max": 9}}, "answer": "a*b*10^6", "sigFigs": 2}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE1'), 'Which is bigger: 10^100 or 100^10? By roughly how much?', '10^100 — 100^10 = 10^20, so it''s larger by a factor of 10^80.', NULL, 'hard', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE1'), '0.0004 × 0.002 = ? Answer in scientific notation.', '8 × 10^−7 ((4×10^−4)(2×10^−3))', NULL, 'hard', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE1'), 'A billion seconds is roughly how many years? Show the powers of ten.', '≈32 years (10^9 s ÷ ~3.15×10^7 s/yr)', NULL, 'hard', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR1'), 'A recipe uses {a} cups of flour for 12 cookies. How much flour for 36 cookies?', 'Triple it — 36 is 3 × 12.', NULL, 'easy', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 2, "max": 4}}, "answer": "a*3", "answerUnit": "cups"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR1'), '{a} granola bars cost ${b}. What does one cost?', 'Divide the total by the count.', NULL, 'easy', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 3, "max": 6}, "b": {"min": 3, "max": 12, "step": 3}}, "answer": "b/a", "answerUnit": "$", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR1'), 'A map says 1 cm = 5 km. How far is {a} cm on the map?', 'Multiply by 5.', NULL, 'easy', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 3, "max": 12}}, "answer": "a*5", "answerUnit": "km"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR1'), 'You read 20 pages in 30 minutes. How long for 60 pages?', '90 minutes — 3 times the pages, 3 times the time.', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR1'), 'Which is the better buy: 6 rolls for $4.50 or 8 rolls for $5.60?', '8 for $5.60 (70¢ each vs 75¢ each)', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR1'), 'Socks come 3 pairs to a pack. How many packs for {a} pairs?', 'Divide by 3.', NULL, 'easy', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 9, "max": 27, "step": 3}}, "answer": "a/3", "answerUnit": "packs"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR1'), 'A car uses {a} gallons to go {b} miles. At that rate, how far on 10 gallons?', 'Find miles per gallon, then scale.', NULL, 'medium', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 2, "max": 5}, "b": {"min": 60, "max": 150, "step": 10}}, "answer": "10*b/a", "answerUnit": "miles", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR1'), 'A photo is 4 in wide and 6 in tall. You enlarge it to 10 in wide. How tall is it now?', '15 in — same 2:3 shape (×2.5)', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR1'), 'Paint covers {a} m² per liter. How many liters for a {b} m² wall?', 'Divide area by coverage.', NULL, 'medium', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 8, "max": 12}, "b": {"min": 40, "max": 120, "step": 8}}, "answer": "b/a", "answerUnit": "L", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR1'), '{a} identical tickets cost ${b}. What do 7 tickets cost?', 'Cost per ticket times 7.', NULL, 'medium', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 2, "max": 4}, "b": {"min": 24, "max": 60, "step": 12}}, "answer": "7*b/a", "answerUnit": "$", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR1'), 'A 5-lb bag of rice serves 18 people. How many pounds to serve 45?', '12.5 lb (45/18 = 2.5 × the bag)', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR1'), 'Two towns are {a} cm apart on a map with scale 1 : 250,000. How far apart in km?', 'Each cm is 2.5 km.', NULL, 'medium', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 4, "max": 20, "step": 2}}, "answer": "a*2.5", "answerUnit": "km"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR1'), 'A crew of 4 paints a fence in 6 hours. How long for a crew of 8 at the same pace?', '3 hours — twice the workers, half the time (inverse, not direct!).', NULL, 'hard', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR1'), 'Lemonade mix: 3 parts mix to 8 parts water. How much mix in 44 cups of drink?', '12 cups (44 ÷ 11 parts = 4 per part; mix = 3 parts)', NULL, 'hard', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR1'), 'A phone battery loses {a}% in 45 minutes of video. Roughly how many minutes of video from full?', 'Scale 45 minutes up to 100%.', NULL, 'hard', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 10, "max": 30, "step": 5}}, "answer": "45*100/a", "answerUnit": "min", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR2'), 'y is proportional to x. If x doubles, what happens to y?', 'It doubles too.', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR2'), 'y = 12/x. If x doubles, what happens to y?', 'It halves (inverse: bigger bottom, smaller value).', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR2'), 'Sharing a $60 prize equally: each of 4 friends gets $15. If 8 friends share, each gets?', '$7.50 — twice the people, half each.', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR2'), 'y is proportional to x, and y = {a} when x = 2. What is y when x = 6?', 'x tripled, so y triples.', NULL, 'easy', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 4, "max": 20, "step": 2}}, "answer": "a*3"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR2'), 'A faucet fills a tub in 12 minutes. Two identical faucets together take?', '6 minutes.', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR2'), 'y = k·x². If x doubles, y becomes how many times bigger?', '4 times (2² = 4).', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR2'), 'y = k/x², and y = {a} when x = 1. What is y when x = 2?', 'Quarter it — inverse SQUARE.', NULL, 'medium', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 16, "max": 96, "step": 16}}, "answer": "a/4"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR2'), 'Wi-Fi signal drops with the square of distance. At 2 m the bars read 36 units. At 6 m?', '4 units (3× the distance → 1/9 the signal).', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR2'), 'A square photo''s side doubles. What happens to the area? The perimeter?', 'Area ×4, perimeter ×2 — area grows with the square.', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR2'), 'y = k·x and y = {a} when x = {b}. Find y when x = {c}.', 'Find k = y/x first, then scale.', NULL, 'medium', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 6, "max": 30, "step": 6}, "b": {"min": 2, "max": 5}, "c": {"min": 6, "max": 12}}, "answer": "a*c/b", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR2'), 'Travel time for a fixed trip is inversely proportional to speed. Going 1.5× as fast changes the time how?', 'Time becomes 2/3 of what it was.', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR2'), 'y = k/x², and y = {a} when x = 6. What is y when x = 3?', 'Half the x → 4 times the y.', NULL, 'medium', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 2, "max": 10}}, "answer": "a*4"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR2'), 'A pizza''s diameter goes from 10 in to 14 in. How much more pizza is that?', 'Roughly double — area scales with diameter², (14/10)² ≈ 1.96.', NULL, 'hard', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR2'), 'y = k·x³ (cube). If x is halved, y becomes?', '1/8 of the original.', NULL, 'hard', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='PR2'), 'Streaming quality q = k/x² where x is ''distance from router''. You move from 8 m to 2 m. Quality changes by what factor?', '×16 — distance fell to 1/4, so q rises by 4² = 16.', NULL, 'hard', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE2'), 'Convert {a} cm to meters.', 'Divide by 100.', NULL, 'easy', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 120, "max": 900, "step": 20}}, "answer": "a/100", "answerUnit": "m", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE2'), 'Convert {a} minutes to hours.', 'Divide by 60.', NULL, 'easy', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 90, "max": 300, "step": 15}}, "answer": "a/60", "answerUnit": "h", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE2'), 'Convert {a} mL to liters.', 'Divide by 1000.', NULL, 'easy', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 250, "max": 4000, "step": 250}}, "answer": "a/1000", "answerUnit": "L", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE2'), 'Convert {a} kg to grams.', 'Multiply by 1000.', NULL, 'easy', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 2, "max": 9}}, "answer": "a*1000", "answerUnit": "g"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE2'), 'A movie is {a} minutes long. Express that in hours and minutes.', 'Divide by 60; the remainder is minutes.', NULL, 'easy', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 95, "max": 150, "step": 5}}, "answer": "a/60", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE2'), 'Which is longer: 2,500 m or 2.4 km?', '2,500 m (= 2.5 km)', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE2'), 'Grapes are ${a} per kg. What do {b}00 g cost?', 'Convert grams to kg first.', NULL, 'medium', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 4, "max": 9}, "b": {"min": 2, "max": 8}}, "answer": "a*b/10", "answerUnit": "$", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE2'), 'A printer prints {a} pages per minute. How many pages per hour?', 'Multiply by 60.', NULL, 'medium', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 8, "max": 30, "step": 2}}, "answer": "a*60", "answerUnit": "pages"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE2'), 'Convert {a} m/min into cm/s.', '×100 for cm, ÷60 for seconds.', NULL, 'medium', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 6, "max": 30, "step": 6}}, "answer": "a*100/60", "answerUnit": "cm/s", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE2'), 'Your answer for a length comes out in ''dollars''. What does that tell you?', 'The setup is wrong — units must survive the calculation; recheck which quantities were multiplied or divided.', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE2'), 'Water drips at 3 mL per minute. How many liters per day?', '4.32 L (3 × 60 × 24 = 4,320 mL)', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE2'), '{a} km in {b} minutes — what speed in km/h?', 'Scale the minutes up to an hour.', NULL, 'medium', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 5, "max": 30, "step": 5}, "b": {"min": 10, "max": 50, "step": 10}}, "answer": "a*60/b", "answerUnit": "km/h", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE2'), 'Convert {a} km/h to m/s.', '×1000 then ÷3600 (divide by 3.6).', NULL, 'hard', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 18, "max": 108, "step": 9}}, "answer": "a/3.6", "answerUnit": "m/s", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE2'), 'A recipe wants 350°F but your oven is Celsius. About what setting? (°C = (°F−32)·5/9)', '≈177°C (usually round to 180°C)', NULL, 'hard', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE2'), 'A dose is 5 mg per kg of body weight per day, split in 2 doses. For a 24-kg child, how much per dose?', '60 mg (120 mg/day ÷ 2) — units carried: mg/kg × kg → mg.', NULL, 'hard', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE4'), 'How many significant figures in 0.00420?', 'Three — the leading zeros only place the decimal; the trailing zero counts.', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE4'), 'Round {a}.{b}472 to three significant figures.', 'Keep three digits, look at the fourth to round.', NULL, 'easy', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 1, "max": 9}, "b": {"min": 1, "max": 9}}, "answer": "a + b/10 + 0.047", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE4'), 'How many significant figures in 1,500? Why is it ambiguous?', 'Could be 2, 3, or 4 — trailing zeros with no decimal point are unclear; scientific notation fixes it.', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE4'), 'A scale reads to the nearest 0.1 g. You weigh a coin at 5.7 g. Can you report 5.70 g?', 'No — 5.70 claims precision to 0.01 g that the scale doesn''t have.', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE4'), 'Round 0.08155 to two significant figures.', '0.082', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE4'), 'Which is more precise: 12.0 cm or 12 cm?', '12.0 cm — it claims the tenths digit is known.', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE4'), 'You measure a table as 1.2 m and 0.85 m. Multiplying gives 1.02 m². How should you report the area?', '1.0 m² — the answer keeps the FEWEST sig figs of the inputs (2).', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE4'), 'Add 12.11 + 0.3 + 5.027. How should the sum be reported?', '17.4 — addition keeps the fewest DECIMAL PLACES (the 0.3).', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE4'), 'Your calculator says {a}.{b}285714. The inputs each had 2 sig figs. Report the answer.', 'Two sig figs only.', NULL, 'medium', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 1, "max": 9}, "b": {"min": 1, "max": 9}}, "answer": "a + b/10", "sigFigs": 2}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE4'), 'A friend reports a walk as 2.000 km measured ''roughly with a phone''. What''s wrong?', 'False precision — the trailing zeros claim metre-level certainty a rough app can''t give; 2.0 km is honest.', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE4'), 'Express 1,500 with exactly three significant figures.', '1.50 × 10^3', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE4'), 'Percent error: you estimated {a}0 and the true value was 100. What is the percent error?', 'Difference over true value, ×100.', NULL, 'medium', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 6, "max": 14}}, "answer": "abs(a*10-100)"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE4'), 'Two measurements: 9.8 ± 0.2 and 9.5 ± 0.2. Are they really different?', 'Not clearly — their uncertainty ranges overlap (9.6–10.0 vs 9.3–9.7).', NULL, 'hard', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE4'), 'Why is 0.5 × 224 = 112 reported as 100 (1 sig fig) sometimes wrong in practice?', 'If the 0.5 is an EXACT number (like ''half''), it has infinite sig figs — only measured values limit precision.', NULL, 'hard', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE4'), 'A stopwatch shows 12.31 s but your reaction time is about 0.2 s. How should you report the time?', '12.3 s at best — the last digit is swamped by the ±0.2 s human uncertainty.', NULL, 'hard', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE3'), 'About how many minutes are in a year: 10^4, 10^5, or 10^6?', '≈5 × 10^5 — closest to 10^6 side of 10^5 (525,600).', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE3'), 'Estimate: how many slices of bread does one person eat in a year?', '~2 per day × 365 ≈ 700 (10^3-ish). Any reasoned 300–1500 is fine.', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE3'), 'Roughly how many seconds old is a 16-year-old: 10^7, 10^8, or 10^9?', '≈5 × 10^8 (16 × 3.15×10^7)', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE3'), 'Estimate the number of school days in 4 years of high school.', '≈180 × 4 ≈ 700', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE3'), 'To the nearest power of ten, how many pages are in a typical novel?', '10^2 (a few hundred)', NULL, 'easy', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE3'), 'Estimate {a} × 39 by rounding first.', 'Round 39 to 40, multiply, adjust down a touch.', NULL, 'easy', true, false, false, '{}'::jsonb, '{"vars": {"a": {"min": 11, "max": 29}}, "answer": "a*39", "sigFigs": 2}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE3'), 'Estimate how many text messages a teenager sends in a year. Defend the pieces.', '~50/day × 365 ≈ 2 × 10^4. Accept 5×10^3–10^5 with reasoning.', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE3'), 'About how many breaths do you take in a day?', '~15/min × 60 × 24 ≈ 2 × 10^4', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE3'), 'Estimate the total hours of homework in a school year at 1.5 h per school day.', '≈270 h (1.5 × 180) — a few hundred.', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE3'), 'A stadium holds 60,000 people. Estimate the crowd''s total mass to one power of ten.', '~4 × 10^6 kg (≈70 kg each) → 10^6–10^7 kg.', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE3'), 'Estimate how many golf balls fit in a school backpack.', 'Backpack ~30 L; ball ~40 mL with packing → ~500. Accept 200–1500 reasoned.', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE3'), 'Roughly how much does a year of daily $6 coffee cost?', '≈$2,000 (6 × 365 = 2,190)', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE3'), 'Estimate how many hairs are on a human head, and name your two assumptions.', '~10^5 (density ~200/cm² × ~500 cm² of scalp)', NULL, 'hard', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE3'), 'Estimate how many piano tuners work in a city of 1 million (the classic Fermi chain).', '~10–100: pianos (~1 per 100 people), tunings/yr, jobs a tuner does per year — defend each link.', NULL, 'hard', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='QE3'), 'Could every human fit in Los Angeles? Estimate, don''t look up.', 'Yes — 8×10^9 people at ~4 people/m² need ~2×10^9 m² = 2,000 km²; LA county is ~10,000 km².', NULL, 'hard', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM1'), 'Solve y = x + 7 for x.', 'x = y − 7 (subtract 7 from both sides)', NULL, 'easy', true, false, true, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM1'), 'Solve y = 4x for x.', 'x = y/4 (divide both sides by 4)', NULL, 'easy', true, false, true, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM1'), 'Solve A = l·w for w.', 'w = A/l', NULL, 'easy', true, false, true, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM1'), 'Solve p = t/n for t.', 'Multiply both sides by n: t = p·n.', NULL, 'easy', true, false, true, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM1'), 'Solve y = mx + b for b.', 'b = y − mx', NULL, 'easy', true, false, true, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM1'), 'Solve C = 2πr for r.', 'r = C/(2π)', NULL, 'easy', true, false, true, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM1'), 'Solve y = mx + b for x.', 'Subtract b first, THEN divide by m: x = (y − b)/m.', NULL, 'medium', true, false, true, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM1'), 'Solve p = t/n for n.', 'Multiply by n, divide by p: n = t/p.', NULL, 'medium', true, false, true, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM1'), 'Solve A = ½·b·h for h.', 'h = 2A/b', NULL, 'medium', true, false, true, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM1'), 'Solve s = (a + b)/2 for a.', 'a = 2s − b', NULL, 'medium', true, false, true, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM1'), 'Solve y = k/x for x.', 'Multiply by x, divide by y: x = k/y.', NULL, 'medium', true, false, true, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM1'), 'Solve V = l·w·h for h, and say why you divide by BOTH l and w.', 'h = V/(l·w) — both multiply h, so both must come off.', NULL, 'medium', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM1'), 'Solve y = a·x² for x (x positive).', 'x = √(y/a) — undo the square LAST-applied-first-undone.', NULL, 'hard', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM1'), 'Solve T = c/(a + b) for a.', 'a = c/T − b (multiply by (a+b), divide by T, subtract b)', NULL, 'hard', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM1'), 'Solve m = (y − b)/x for b.', 'b = y − m·x', NULL, 'hard', true, false, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM2'), 'y = {a}x + {b}. Evaluate y when x = {c}.', 'Multiply first, then add.', NULL, 'easy', true, false, true, '{}'::jsonb, '{"vars": {"a": {"min": 2, "max": 6}, "b": {"min": 1, "max": 9}, "c": {"min": 2, "max": 9}}, "answer": "a*c + b"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM2'), 'A = l·w with l = {a} cm and w = {b} cm. Find A with its unit.', 'Multiply; cm × cm = cm².', NULL, 'easy', true, false, true, '{}'::jsonb, '{"vars": {"a": {"min": 3, "max": 12}, "b": {"min": 3, "max": 9}}, "answer": "a*b", "answerUnit": "cm\u00b2"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM2'), 'Average = total ÷ count. Total = {a} points over {b} games.', 'Divide.', NULL, 'easy', true, false, true, '{}'::jsonb, '{"vars": {"a": {"min": 60, "max": 240, "step": 12}, "b": {"min": 3, "max": 12, "step": 3}}, "answer": "a/b", "answerUnit": "points/game", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM2'), 'P = 2l + 2w with l = {a} m, w = {b} m. Find P.', 'Double each, then add.', NULL, 'easy', true, false, true, '{}'::jsonb, '{"vars": {"a": {"min": 4, "max": 15}, "b": {"min": 2, "max": 9}}, "answer": "2*a + 2*b", "answerUnit": "m"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM2'), 'y = x² with x = {a}. Evaluate.', 'Square it.', NULL, 'easy', true, false, true, '{}'::jsonb, '{"vars": {"a": {"min": 3, "max": 12}}, "answer": "a^2"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM2'), 'Cost = ${a} + ${b} per mile, for {c} miles.', 'Flat fee plus rate × miles.', NULL, 'easy', true, false, true, '{}'::jsonb, '{"vars": {"a": {"min": 2, "max": 5}, "b": {"min": 1, "max": 3}, "c": {"min": 4, "max": 15}}, "answer": "a + b*c", "answerUnit": "$"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM2'), 'y = {a}(x − {b}) with x = {c}. Evaluate — parentheses first.', 'Do x − {b} BEFORE multiplying.', NULL, 'medium', true, false, true, '{}'::jsonb, '{"vars": {"a": {"min": 2, "max": 6}, "b": {"min": 1, "max": 5}, "c": {"min": 6, "max": 14}}, "answer": "a*(c-b)"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM2'), 'A = ½bh with b = {a} cm, h = {b} cm.', 'Half of base × height; unit is cm².', NULL, 'medium', true, false, true, '{}'::jsonb, '{"vars": {"a": {"min": 4, "max": 16, "step": 2}, "b": {"min": 3, "max": 11}}, "answer": "a*b/2", "answerUnit": "cm\u00b2"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM2'), 'y = x/( {a} + {b} ) with x = {c}0. Evaluate.', 'Add the bottom first, then divide.', NULL, 'medium', true, false, true, '{}'::jsonb, '{"vars": {"a": {"min": 1, "max": 4}, "b": {"min": 1, "max": 5}, "c": {"min": 3, "max": 9}}, "answer": "c*10/(a+b)", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM2'), 'C = 2πr with r = {a} cm. Evaluate to one decimal.', '2 × π × r.', NULL, 'medium', true, false, true, '{}'::jsonb, '{"vars": {"a": {"min": 3, "max": 12}}, "answer": "2*3.14159*a", "answerUnit": "cm", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM2'), 'y = {a} − 2x with x = {b}. Watch the sign.', 'Multiply first; subtracting a bigger number goes negative.', NULL, 'medium', true, false, true, '{}'::jsonb, '{"vars": {"a": {"min": 4, "max": 10}, "b": {"min": 6, "max": 12}}, "answer": "a - 2*b"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM2'), 'V = x³ with x = {a} cm. Evaluate with the unit.', 'Cube it; cm³.', NULL, 'medium', true, false, true, '{}'::jsonb, '{"vars": {"a": {"min": 2, "max": 6}}, "answer": "a^3", "answerUnit": "cm\u00b3"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM2'), 'y = √(a² + b²) with a = {a}, b = {b}. Evaluate.', 'Square BOTH, add, then root.', NULL, 'hard', true, false, true, '{}'::jsonb, '{"vars": {"a": {"min": 3, "max": 9}, "b": {"min": 4, "max": 12}}, "answer": "sqrt(a^2 + b^2)", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM2'), 'z = (x + y)² with x = {a}, y = {b}. Why isn''t it x² + y²?', 'Add inside first, then square; (x+y)² has the cross term 2xy.', NULL, 'hard', true, false, true, '{}'::jsonb, '{"vars": {"a": {"min": 2, "max": 6}, "b": {"min": 3, "max": 7}}, "answer": "(a+b)^2"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='SM2'), 'y = {a}·2^x with x = {b}. Evaluate.', 'Power first, then multiply.', NULL, 'hard', true, false, true, '{}'::jsonb, '{"vars": {"a": {"min": 2, "max": 5}, "b": {"min": 3, "max": 6}}, "answer": "a*2^b"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV1'), 'A graph of money earned vs hours worked is a straight line through (0, 0) and (4, 60). What is the slope, and what does it mean?', '15 — rise over run; it''s the pay rate in $/hour.', NULL, 'easy', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV1'), 'A line passes through (0, {b}) and ({t}, {y}). What is its slope?', 'Rise over run: change in y over change in x.', NULL, 'easy', true, true, false, '{}'::jsonb, '{"vars": {"b": {"min": 2, "max": 10}, "t": {"min": 2, "max": 6}, "y": {"min": 20, "max": 60, "step": 4}}, "answer": "(y-b)/t", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV1'), 'On a graph of water in a bathtub vs time, what does a NEGATIVE slope mean?', 'The tub is draining — the amount is going down as time passes.', NULL, 'easy', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV1'), 'Two lines on the same earnings-vs-hours graph. How do you spot who earns more per hour?', 'The steeper line — steeper means more $ per hour.', NULL, 'easy', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV1'), 'A graph is a flat horizontal line at y = 12. What is its slope, and what is it saying?', 'Zero — the quantity isn''t changing.', NULL, 'easy', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV1'), 'Pages read vs days is a line through (0,0) and (5, 80). Pages per day?', '16 pages/day', NULL, 'easy', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV1'), 'A line through ({a}, {b}0) and ({c}, {d}0) — find the slope.', 'Δy over Δx, keeping the pairs in the same order.', NULL, 'medium', true, true, false, '{}'::jsonb, '{"vars": {"a": {"min": 1, "max": 3}, "b": {"min": 2, "max": 4}, "c": {"min": 5, "max": 9}, "d": {"min": 6, "max": 9}}, "answer": "(d*10-b*10)/(c-a)", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV1'), 'A savings graph starts at $40 (the y-intercept) and climbs $15 each week. Where is it after {a} weeks?', 'Intercept plus slope × weeks.', NULL, 'medium', true, true, false, '{}'::jsonb, '{"vars": {"a": {"min": 3, "max": 10}}, "answer": "40 + 15*a", "answerUnit": "$"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV1'), 'On a graph of rainfall RATE (cm/hour) vs time, what does the AREA under the curve give?', 'Total rainfall in cm — rate × time adds up the amount.', NULL, 'medium', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV1'), 'A rate graph is flat at {a} L/min for {b} minutes. What does the area under it represent, and how much?', 'Area = rate × time = total liters.', NULL, 'medium', true, true, false, '{}'::jsonb, '{"vars": {"a": {"min": 2, "max": 6}, "b": {"min": 5, "max": 20, "step": 5}}, "answer": "a*b", "answerUnit": "L"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV1'), 'Two points on a line: (2, 10) and (6, 10). Slope? What situation could this be?', 'Zero slope — e.g., a stopped download: no change while time passes.', NULL, 'medium', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV1'), 'A graph shows temperature vs time curving upward, getting steeper. What is happening to the RATE of warming?', 'It''s increasing — steepening slope means warming faster and faster.', NULL, 'medium', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV1'), 'A line has slope −{a} $/day starting from ${b}0 on day 0. When does it hit zero?', 'Set intercept + slope·t = 0 and solve for t.', NULL, 'hard', true, true, false, '{}'::jsonb, '{"vars": {"a": {"min": 2, "max": 5}, "b": {"min": 4, "max": 9}}, "answer": "b*10/a", "answerUnit": "days", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV1'), 'Graph A shows amount vs time; graph B shows the RATE vs time for the same story. How are they related?', 'B is the slope of A at each moment; the area under B recovers A''s change.', NULL, 'hard', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV1'), 'The area under a rate graph from t = 0 to 6 is a triangle with base 6 min and height 12 L/min. Total amount?', '36 L — triangle area ½ × 6 × 12.', NULL, 'hard', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV2'), 'Plotting y vs x gives a curve; plotting y vs x² gives a straight line. What does that tell you?', 'y grows with the SQUARE of x (y = k·x²).', NULL, 'easy', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV2'), 'Data lands on a line through the origin when you plot cost vs weight. What kind of relationship is that?', 'Direct proportion — cost = (price per kg) × weight; the slope is the price.', NULL, 'easy', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV2'), 'You suspect y = k/x. What plot would make the data straight?', 'Plot y vs 1/x — the slope is k.', NULL, 'easy', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV2'), 'A line of best fit on earnings vs hours has slope {a}. What does an extra 3 hours earn?', 'Slope × 3.', NULL, 'easy', true, true, false, '{}'::jsonb, '{"vars": {"a": {"min": 12, "max": 20}}, "answer": "a*3", "answerUnit": "$"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV2'), 'Why draw a best-fit LINE instead of connecting every dot?', 'Measurements wobble; the trend is the signal — dot-to-dot chases the noise.', NULL, 'easy', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV2'), 'A best-fit line on a phone-battery graph drops from 100% at 0 h to 40% at 6 h. Slope, with units?', '−10 %/hour', NULL, 'easy', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV2'), 'y vs x² is a straight line through (0,0) with slope {a}. What is y when x = {b}?', 'y = slope × x².', NULL, 'medium', true, true, false, '{}'::jsonb, '{"vars": {"a": {"min": 2, "max": 5}, "b": {"min": 2, "max": 5}}, "answer": "a*b^2"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV2'), 'y vs 1/x is a line through the origin with slope {a}0. What is y at x = {b}?', 'y = slope/x.', NULL, 'medium', true, true, false, '{}'::jsonb, '{"vars": {"a": {"min": 2, "max": 8}, "b": {"min": 2, "max": 10, "step": 2}}, "answer": "a*10/b", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV2'), 'Your y vs x² plot is straight but does NOT pass through the origin. What does the intercept mean?', 'There''s a starting amount — y = kx² + c; c is y when x = 0.', NULL, 'medium', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV2'), 'One data point sits far off an otherwise straight fit. What should you do first?', 'Suspect and re-check that measurement before letting it drag the fit — don''t silently delete it.', NULL, 'medium', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV2'), 'Doubling x always quadruples y in your table. Which plot straightens it, and what slope do you expect?', 'y vs x²; the slope is y/x² = k.', NULL, 'medium', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV2'), 'A fit gives y = 4.9x² + 0.3 where the 0.3 ''should'' be 0. Is the model wrong?', 'Not necessarily — a small intercept is normal measurement offset; judge it against the data''s scatter.', NULL, 'medium', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV2'), 'Your y vs x data curves DOWN (doubling x less than doubles y). Which straightening plots are worth trying, and how would you decide?', 'Try y vs √x or y² vs x (or log-log) — whichever makes it straight names the power.', NULL, 'hard', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV2'), 'On a log-log plot your data is a line with slope 2. What law is that?', 'y = k·x² — the log-log slope IS the exponent.', NULL, 'hard', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV2'), 'Two fits both look straight: y = 3.1x − 0.2 and y = 2.8x + 1.9. What single extra measurement would best decide between them?', 'One far from the data cluster (x near 0, or a large x) — the lines separate most there.', NULL, 'hard', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV3'), 'You walk 3 blocks east, then 4 blocks north. How far are you from the start, as the crow flies?', '5 blocks (3-4-5 right triangle)', NULL, 'easy', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV3'), 'A ramp rises at {a}° and you travel {b} m along it. How much HEIGHT do you gain?', 'The opposite side: length × sin(angle).', NULL, 'easy', true, true, false, '{}'::jsonb, '{"vars": {"a": {"min": 20, "max": 50, "step": 5}, "b": {"min": 10, "max": 40, "step": 5}}, "answer": "b*sin(a)", "answerUnit": "m", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV3'), 'You walk {b} m at {a}° north of east. How far EAST have you gone?', 'The adjacent side: length × cos(angle).', NULL, 'easy', true, true, false, '{}'::jsonb, '{"vars": {"a": {"min": 20, "max": 60, "step": 5}, "b": {"min": 10, "max": 50, "step": 10}}, "answer": "b*cos(a)", "answerUnit": "m", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV3'), 'A drone flies 8 km east then 8 km north. In what compass direction is it from home?', 'Exactly northeast (45° north of east — equal legs).', NULL, 'easy', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV3'), 'Which is longer: walking 6 m east then 8 m north, or walking the 10 m diagonal?', 'The two-leg path (14 m) — the diagonal is the shortcut.', NULL, 'easy', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV3'), 'You walk {a} m east, then {b} m north. How many metres did you WALK in total (path length, not distance from start)?', 'Path length just adds the legs; the crow-flies distance would need the triangle.', NULL, 'easy', true, true, false, '{}'::jsonb, '{"vars": {"a": {"min": 2, "max": 9}, "b": {"min": 2, "max": 9}}, "answer": "a+b", "answerUnit": "m"}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV3'), 'You go {a} m east then {b} m north. How far from the start?', '√(east² + north²).', NULL, 'medium', true, true, false, '{}'::jsonb, '{"vars": {"a": {"min": 5, "max": 12}, "b": {"min": 5, "max": 12}}, "answer": "sqrt(a^2+b^2)", "answerUnit": "m", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV3'), 'A kite string is {b} m long at {a}° above level ground. How high is the kite?', 'height = length × sin(angle).', NULL, 'medium', true, true, false, '{}'::jsonb, '{"vars": {"a": {"min": 30, "max": 70, "step": 5}, "b": {"min": 20, "max": 60, "step": 10}}, "answer": "b*sin(a)", "answerUnit": "m", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV3'), 'Two moves: 5 m east + 2 m west, and 7 m north + 3 m south. What is the net (east, north)?', '(3 m east, 4 m north) — opposite directions subtract.', NULL, 'medium', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV3'), 'Does walking A-then-B land you in the same place as B-then-A?', 'Yes — vector addition doesn''t care about order (the parallelogram closes).', NULL, 'medium', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV3'), 'A treasure map: {b}0 paces at {a}° north of east. How many paces NORTH is the treasure?', 'north = length × sin(angle).', NULL, 'medium', true, true, false, '{}'::jsonb, '{"vars": {"a": {"min": 25, "max": 65, "step": 5}, "b": {"min": 3, "max": 9}}, "answer": "b*10*sin(a)", "answerUnit": "paces", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV3'), 'At what angle are the east and north parts of a walk exactly equal?', '45° — sin and cos match there.', NULL, 'medium', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV3'), 'You walk 30 m at 30° north of east, then 30 m at 60° north of east. Without computing, is the answer''s direction 45°? Why?', 'Yes — by symmetry the two legs mirror around 45°; magnitudes equal, so the resultant bisects.', NULL, 'hard', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV3'), 'A move of {b} m at {a}° north of east — write BOTH components, then check them with the Pythagorean theorem.', 'east = cos, north = sin; components must rebuild the length.', NULL, 'hard', true, true, false, '{}'::jsonb, '{"vars": {"a": {"min": 25, "max": 65, "step": 10}, "b": {"min": 10, "max": 50, "step": 10}}, "answer": "sqrt((b*cos(a))^2 + (b*sin(a))^2)", "answerUnit": "m", "sigFigs": 3}'::jsonb, 'claude-cowork 2026-08-27'),
((select id from math_competencies where code='GV3'), 'Why does a 10 m walk at 80° north of east move you barely 1.7 m east?', 'cos(80°) ≈ 0.17 — near-vertical directions starve the east component; components are projections, not shares.', NULL, 'hard', true, true, false, '{}'::jsonb, NULL, 'claude-cowork 2026-08-27');
